using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BOApply {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B2/";
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_OperationsRebuild/";
 static Scene Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 edit required");return s;}
 static GameObject Group(string n,Transform p){var g=new GameObject(n);g.transform.SetParent(p,false);return g;}
 static Vector3 V(JToken v)=>new Vector3((float)v[0],(float)v[1],(float)v[2]);
 public static object Import(){Check();AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var mats=AssetDatabase.FindAssets("t:Material",new[]{E+"Materials"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<Material>).Where(m=>m.name.StartsWith("BCM_")).ToDictionary(m=>"B4O_"+m.name.Substring(4));mats["B2M_Plate"]=mats["B4O_Plate"];foreach(string n in new[]{"Pipe","PipeRed"})mats["BM_"+n]=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/BM_"+n+".mat");int count=0;foreach(var p in Directory.GetFiles(E,"BO_*Operations*.fbx").Select(x=>x.Replace('\\','/'))){var mi=(ModelImporter)AssetImporter.GetAtPath(p);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;foreach(var kv in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);mi.SaveAndReimport();count++;}AssetDatabase.SaveAssets();return new{models=count};}
 static GameObject Put(string asset,Transform parent,bool collision=false){var src=AssetDatabase.LoadAssetAtPath<GameObject>(E+asset+".fbx");if(!src)throw new Exception("Missing "+asset);var g=(GameObject)PrefabUtility.InstantiatePrefab(src,parent);g.transform.localPosition=Vector3.zero;g.transform.localRotation=Quaternion.identity;g.name=asset;var original=g.GetComponentsInChildren<MeshRenderer>();if(collision){foreach(var f in g.GetComponentsInChildren<MeshFilter>()){f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;f.GetComponent<MeshRenderer>().enabled=false;}}else{var far=AssetDatabase.LoadAssetAtPath<GameObject>(E+asset+"_LOD1.fbx");if(far){var low=(GameObject)PrefabUtility.InstantiatePrefab(far,g.transform);low.name="Distance_LOD1";low.transform.localPosition=Vector3.zero;low.transform.localRotation=Quaternion.identity;var lg=g.AddComponent<LODGroup>();lg.fadeMode=LODFadeMode.CrossFade;lg.SetLODs(new[]{new LOD(.14f,original.Cast<Renderer>().ToArray()),new LOD(0,low.GetComponentsInChildren<Renderer>())});lg.RecalculateBounds();}}
 return g;}
 static void Save(Scene s){foreach(var t in s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Transform>(true)))if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);foreach(var c in t.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}Physics.SyncTransforms();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);}
 public static object C02()=>Run(true);public static object Remaining()=>Run(false);
 static object Run(bool first){var s=Check();var plan=JObject.Parse(File.ReadAllText(H+"plan.json"));var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var network=s.GetRootGameObjects().Single(g=>g.name=="B2_MachineryNetwork").transform;var root=network.Find("B2_OperationsLayout");if(!root)root=Group("B2_OperationsLayout",network).transform;int n=0;
 foreach(var r in plan["rooms"].Where(r=>((string)r["id"]=="C02")==first)){string id=(string)r["id"];if(root.Find("B2_"+id+"_Operations"))throw new Exception("Already applied "+id+"; use scoped repairs");var room=Group("B2_"+id+"_Operations",root).transform;room.localPosition=new Vector3((float)r["x"],0,-(float)r["v"]);
 foreach(var p in plan["placements"].Where(p=>(string)p["room"]==id)){string source=(string)p["source"];var src=all.Single(t=>t.name==source);string category=(string)p["group"];var subgroup=room.Find(category);if(!subgroup)subgroup=Group(category,room).transform;var g=UnityEngine.Object.Instantiate(src.gameObject,subgroup);g.name=(string)p["name"];g.SetActive(true);g.transform.localPosition=V(p["position"]);g.transform.localRotation=Quaternion.Euler(0,(float)p["yaw"],0);n++;}
 var sector=id=="C02"?s.GetRootGameObjects().Single(g=>g.name=="B2_C02_CoolingSector").transform:network.Find("B2_"+id+"_Sector");if(!sector)throw new Exception("Missing sector "+id);var old=sector.Find("Equipment");foreach(var child in old.Cast<Transform>().ToArray())if(!child.name.Contains("WallSafety")&&!child.name.Contains("CCTV"))child.gameObject.SetActive(false);
 var island=all.SingleOrDefault(t=>t.name=="B2_"+id+"_ProcessIsland");if(island)island.gameObject.SetActive(false);
 var connections=network.Find("B2_DetailPass/EquipmentConnections");foreach(var child in connections.Cast<Transform>().Where(t=>t.name.StartsWith("B2_"+id+"_")).ToArray())child.gameObject.SetActive(false);
 if(plan["decks"][id]!=null){if(id=="C02"){sector.Find("Mezzanine").gameObject.SetActive(false);all.Single(t=>t.name=="B2_C02_UpperTunnelConnection").gameObject.SetActive(false);}else all.Single(t=>t.name=="B2_"+id+"_ServiceMezzanine").gameObject.SetActive(false);Put("BO_"+id+"_OperationsDeck",room);Put("BO_"+id+"_OperationsDeck_Collision",room,true);}
 var services=Put("BO_"+id+"_OperationsServices",room);foreach(var mf in services.GetComponentsInChildren<MeshFilter>().Where(m=>m.transform.parent==room||m.gameObject==services))mf.gameObject.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;
 }
 foreach(var c in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)))c.useOcclusionCulling=false;
 Save(s);File.WriteAllText(H+(first?"apply_c02.json":"apply_remaining.json"),JsonConvert.SerializeObject(new{placements=n,first,saved=!s.isDirty}));return new{placements=n,first,saved=!s.isDirty};}
}
